-- Authentic Z (2335368829): which of its foods are exempt from the loose-food mechanic.
-- Generated by docs/DontSpillTheBeans/tools/food-rules/export-lua.py from food-rules-progress-AuthZ-10-24-26.json;
-- regenerate it instead of editing by hand. Ids for items that are not installed are harmless.
-- Closed cans/jars and foods with no nutrition are handled by rule and are not listed.

require "DSTB_Config"

local Config = DontSpillTheBeans.Config

-- Marks foods as liquidy (they wet what they spill on, not just stain it), or clears the mark.
local function liquid(yes, ids)
    for _, id in ipairs(ids) do Config.LiquidFoods[id] = yes or nil end
end

-- Sets exactly one rule per id, replacing any earlier (default or other-file) entry for it.
local function rule(name, ids)
    for _, id in ipairs(ids) do
        Config.FoodExempt[id], Config.FoodExemptWhenUneaten[id] = nil, nil
        if name == "exempt" then Config.FoodExempt[id] = true
        elseif name == "whole" then Config.FoodExemptWhenUneaten[id] = true
        end
    end
end

-- Always exempt (5)
rule("exempt", {
    "AuthenticZBackpacksPlus.BigLollipop", "AuthenticZBackpacksPlus.PopBottle", "AuthenticZClothing.BigLollipop",
    "AuthenticZClothing.PopBottle", "AuthenticZLite.BigLollipop",
})

-- Liquidy foods: soups, stews... (2 yes, 11 marked not liquid)
liquid(true, {
    "AuthenticZBackpacksPlus.PopBottle", "AuthenticZClothing.PopBottle",
})
liquid(false, {
    "AuthenticZBackpacksPlus.BigLollipop", "AuthenticZClothing.AuthenticCigaretteHolder",
    "AuthenticZClothing.AuthenticCigaretteHolder_Cig", "AuthenticZClothing.BigLollipop",
    "AuthenticZClothing.CigarAZ2", "AuthenticZClothing.CigarAZHalf", "AuthenticZLite.AuthenticCigaretteHolder",
    "AuthenticZLite.AuthenticCigaretteHolder_Cig", "AuthenticZLite.BigLollipop", "AuthenticZLite.CigarAZ2",
    "AuthenticZLite.CigarAZHalf",
})
